import { createContext, FC, memo, ReactNode, useState } from 'react';

export const PanelTotalContext = createContext({
  redSheet: 0,
  greenSheet: 0,
  whiteSheet: 0,
  blueSheet: 0,
});
// export const PanelTotalContext = createContext(0);

// type Props = {
//   children: ReactNode;
// };

export const PanelTotalProvider: FC = memo(() => {
  const [panelTotals, setPanelTotal] = useState({
    redSheet: 0,
    greenSheet: 0,
    whiteSheet: 0,
    blueSheet: 0,
  });
  // const [panelTotal, setPanelTotal] = useState(0);
  return (
    <PanelTotalContext.Provider
      value={[
        panelTotals.redSheet,
        panelTotals.greenSheet,
        panelTotals.whiteSheet,
        panelTotals.blueSheet,
        setPanelTotal,
      ]}
    >
      {props.children}
    </PanelTotalContext.Provider>
  );
});
